function useSelect(options: Option[]) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);

  function getTriggerProps() {
    return {
      onClick: () => setOpen((o) => !o),
      'aria-expanded': open,
    };
  }
  function getOptionProps(i: number) {
    return {
      onClick: () => { setActive(i); setOpen(false); },
      style: { background: i === active ? '#eef' : '#fff' },
    };
  }
  return { open, getTriggerProps, getOptionProps };
}
